#
# The rule id is the identity: file name, control id and `tag checkov_id` all
# carry it, and tools/lint_catalog_drift.py asserts the three agree.

scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_17'] || []

control 'CKV_AWS_17' do
  title 'Ensure all data stored in RDS is not publicly accessible'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_db_instance resources that actually exist, read through the
    stock inspec-aws aws_rds_instance resource.
  DESC

  desc 'rationale', <<~RATIONALE
    A publicly accessible instance is reachable from the internet, so its
    exposure is bounded only by credentials and the security group.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_db_instance: publicly_accessible is not True;
    aws_rds_cluster_instance: publicly_accessible is not True
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_db_instance:

      resource "aws_db_instance" "example" {
        publicly_accessible = false
      }

    Out of band — aws_db_instance:

      aws rds modify-db-instance --db-instance-identifier <id> --no-publicly-accessible --apply-immediately
  FIX

  tag checkov_id:            'CKV_AWS_17'
  tag checkov_category:      'NETWORKING'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'negative'
  tag tf_resources:          %w[aws_db_instance aws_rds_cluster_instance]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/db_instance#publicly-accessible'
  tag nist:                  ['SC-7', 'SC-7 (5)']
  tag nist_r4:               ['SC-7', 'SC-7 (5)']
  tag cci:                   ['CCI-001097', 'CCI-002080']
  tag ksi:                   ['KSI-CNA-NDS']
  tag severity:              'high'
  tag severity_source:       'assessed'
  tag nist_source:           'reviewed'
  tag implementation_status: 'implemented'

  # Enumerated at control scope, then each asset asserted on its own. The
  # resource is an ARGUMENT to `describe`, which evaluates on the control --
  # calling it inside the block would defer it into the example.
  #
  # Every call carries aws_region: a stock resource otherwise reads only the
  # region the connection was built with, and every other region's resources
  # report as absent, which renders Not Applicable rather than unexamined.
  #
  # checkov_enumerate does the reading. It flattens a nested id column, tells an
  # unregistered column apart from an account that simply has none of this
  # resource, and hands back anything that stopped it as `problems` rather than
  # as an empty list -- see libraries/_checkov_enumeration.rb.
  problems = []
  found = checkov_scan_regions(scan_regions).flat_map do |region|
    ids, found_problems = checkov_enumerate(
      aws_rds_instances(aws_region: region), :db_instance_identifiers
    )
    problems.concat(found_problems.map { |p| "#{region}: #{p}" })
    ids.map { |id| [id, region] }
  end

  # The region LIST is upstream of every enumeration above, and its failure
  # is the one that hides best: no regions means no rows, no rows means no
  # problems, and the control renders Not Applicable across the whole account
  # while a denied ec2:DescribeRegions goes unreported. checkov_scan_regions
  # falls back to the connection's own region and records that here, so a
  # partial scan fails loudly instead of passing quietly.
  problems.concat(checkov_region_problems)

  # Blank ids are separated out and asserted on below rather than filtered away,
  # so a wrong `ids` column is a visible failure and not a silent Not Applicable.
  # `id.nil?` before the interpolation on purpose: a NullResponse answers true to
  # nil? but interpolates to "#<NullResponse:0x...>", which is not blank. The
  # survivors are interpolated rather than `.to_s`'d, because to_s on a
  # NullResponse returns nil and the singular then rejects the argument.
  unusable = found.count { |id, _r| id.nil? || "#{id}".strip.empty? }
  found = found.reject { |id, _r| id.nil? || "#{id}".strip.empty? }
               .map { |id, region| ["#{id}", region] }
  in_scope = found.reject { |id, _r| checkov_exempt?(id: id, type: 'aws_db_instance', rules: exempt) }

  if unusable.positive? || problems.any?
    describe "aws_db_instance enumeration" do
      it 'produced usable identifiers' do
        expect(unusable).to eq(0),
          "#{unusable} row(s) had a blank id — the `ids` column in resource_map.yml "\
          'likely names a field this resource does not expose'
      end

      it 'read the assets it set out to read' do
        expect(problems).to be_empty
      end
    end
  end

  # `unusable.positive? || problems.any?` keeps the control APPLICABLE when the
  # enumeration broke. Without it only_if skips the control, and the broken cases
  # these guards exist to catch are exactly the ones it would suppress — a Not
  # Applicable that means "nobody looked".
  applicable = !in_scope.empty? || unusable.positive? || problems.any?
  impact 0.7
  impact 0.0 unless applicable
  only_if('no aws_db_instance in scope') { applicable }

  # Every asset is READ at control scope before anything is asserted on it, and
  # the reads that failed are reported as reads that failed. `describe
  # singular(...) { its(prop) }` cannot tell them apart: a stock resource that
  # finds nothing answers every property with a NullResponse, which compares
  # unequal to the expected value and renders as a finding (#16, #17). See
  # checkov_stock_value in libraries/_checkov_enumeration.rb.
  unreadable = []
  readings = in_scope.filter_map do |id, region|
    value, fault = checkov_stock_value(aws_rds_instance(db_instance_identifier: id, aws_region: region), 'publicly_accessible')
    where = region ? "#{id} in #{region}" : id
    if fault
      unreadable << "#{where}: #{fault}"
      next
    end
    [where, value]
  end

  unless unreadable.empty?
    describe 'aws_db_instance read-back' do
      it 'read every asset the enumeration named' do
        # The count is asserted and the list is in the message: RSpec truncates
        # an inspected collection to a couple of hundred characters with the
        # middle elided, and the evidence would lose the assets it is about.
        expect(unreadable.length).to eq(0),
          "#{unreadable.length} of #{in_scope.length} aws_db_instance asset(s) were enumerated but could "\
          "not be read by aws_rds_instance, so NOTHING was assessed for them: "\
          "#{unreadable.first(5).join('; ')}"
      end
    end
  end

  readings.each do |where, value|
    describe "aws_db_instance #{where} publicly_accessible" do
      subject { value }
      it { should eq false }
    end
  end
end
